import{_ as r,o as d,c as o,a2 as a}from"./chunks/framework.e4u2V5E7.js";const _=JSON.parse('{"title":"المعجم","description":"مصطلحات ومفاهيم مساحة العمل","frontmatter":{"title":"المعجم","description":"مصطلحات ومفاهيم مساحة العمل"},"headers":[],"relativePath":"ar/glossary.md","filePath":"ar/glossary.md","lastUpdated":1784504465000}'),e={name:"ar/glossary.md"};function n(s,t,g,l,i,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="المعجم" tabindex="-1">المعجم <a class="header-anchor" href="#المعجم" aria-label="Permalink to &quot;المعجم&quot;">​</a></h1><h2 id="مصطلحات-أساسية" tabindex="-1">مصطلحات أساسية <a class="header-anchor" href="#مصطلحات-أساسية" aria-label="Permalink to &quot;مصطلحات أساسية&quot;">​</a></h2><table tabindex="0"><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td><strong>وكيل (Agent)</strong></td><td>مساعد ذكاء ااصطناعي متخصص في مجال محدد من هندسة البرمجيات</td></tr><tr><td><strong>مهارة (Skill)</strong></td><td>وحدة معرفية قابلة للتحميل عند الطلب</td></tr><tr><td><strong>أمر (Command)</strong></td><td>أمر شاشة موجه يُنفّذ سير عمل محدد</td></tr><tr><td><strong>دليل إرشاد (Playbook)</strong></td><td>خطوات عملية لسير عمل معقد</td></tr><tr><td><strong>مولّد (Generator)</strong></td><td>أداة لإنشاء مكونات جديدة تلقائيًا</td></tr><tr><td><strong>وثيقة معرفية (Knowledge Doc)</strong></td><td>مرجع تخصصي لمجال محدد</td></tr><tr><td><strong>مساحة العمل (Workspace)</strong></td><td>المجلد الرئيسي الذي تحتوي على جميع المكونات</td></tr><tr><td><strong>الطبقة الشخصية (Personal Layer)</strong></td><td>تفضيلات المستخدم الخاصة</td></tr><tr><td><strong>الطبقة المهنية (Professional Layer)</strong></td><td>معايير الهندسة الشاملة</td></tr><tr><td><strong>الطبقة المجالية (Domain Layer)</strong></td><td>معرفة التخصص</td></tr></tbody></table><h2 id="مصطلحات-تقنية" tabindex="-1">مصطلحات تقنية <a class="header-anchor" href="#مصطلحات-تقنية" aria-label="Permalink to &quot;مصطلحات تقنية&quot;">​</a></h2><table tabindex="0"><thead><tr><th>المصطلح</th><th>التعريف</th></tr></thead><tbody><tr><td><strong>ADR</strong></td><td>قرار هندسي (Architecture Decision Record)</td></tr><tr><td><strong>OWASP</strong></td><td>مشروع أمان تطبيقات الويب المفتوح</td></tr><tr><td><strong>RTL</strong></td><td>من اليمين إلى اليسار (Right-to-Left)</td></tr><tr><td><strong>A11y</strong></td><td>إمكانية الوصول (Accessibility)</td></tr><tr><td><strong>RAG</strong></td><td>توليد المعرفة المعززة (Retrieval-Augmented Generation)</td></tr><tr><td><strong>MCP</strong></td><td>بروتوكول سياق النموذج (Model Context Protocol)</td></tr></tbody></table>',5)])])}const b=r(e,[["render",n]]);export{_ as __pageData,b as default};
